def _parse_attrs(options: Dict[str, Any]) ->Dict[str, Any]:
    attrs = {}
    for key, value in options.items():
        if key in ('alt', 'width', 'height'):
            attrs[key] = value
        elif key == 'target':
            attrs['href'] = escape_url(value)
        elif key == 'class':
            attrs['class'] = value
        elif key == 'id':
            attrs['id'] = value
        elif key == 'align':
            if value in _allowed_aligns:
                if 'class' in attrs:
                    attrs['class'] += ' align-' + value
                else:
                    attrs['class'] = 'align-' + value
        else:
            attrs[key] = value
    return attrs
